def find_blocks(g):
    H,W=len(g),len(g[0]); out=[]
    for i in range(H-2):
        for j in range(W-2):
            c=g[i][j]
            if c and all(g[i+a][j+b]==c for a in range(3) for b in range(3)):
                out.append((c,i+1,j+1))
    return out
def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    blocks=find_blocks(g)
    hlines={}; vlines={}
    for c,i,j in blocks:
        hlines[i]=c; vlines[j]=c
    for i,c in hlines.items():
        for j in range(W): out[i][j]=c
    for j,c in vlines.items():
        for i in range(H): out[i][j]=c
    for i,ch in hlines.items():
        for j,cv in vlines.items():
            if ch!=cv: out[i][j]=0
    return out
